import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;

        int[] stack = new int[n];
        int top = 0;

        for (int i = 0; i < n; i++) {
            in.nextToken();
            int x = (int) in.nval;
            if (x == 0) {
                if (top > 0) top--; // desfaz o último número válido
            } else {
                stack[top++] = x;
            }
        }

        long sum = 0;
        for (int i = 0; i < top; i++) sum += stack[i];

        System.out.println(sum);
    }
}
